import 'package:flutter/material.dart'; import '../models/question_model.dart'; class QuestionWidget extends StatelessWidget { final QuestionModel question; final String? value; final ValueChanged<String?> onChanged; const QuestionWidget({super.key,required this.question,required this.value,required this.onChanged}); @override Widget build(BuildContext c){ if(question.questionType==QuestionType.shortAnswer)return TextField(onChanged:(v)=>onChanged(v),decoration:InputDecoration(labelText:question.text,border:const OutlineInputBorder())); final opts=question.questionType==QuestionType.trueFalse?const ['true','false']:question.options; return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(question.text,style:Theme.of(c).textTheme.titleMedium),...opts.map((o)=>RadioListTile<String>(value:o,groupValue:value,onChanged:onChanged,title:Text(o)))]))); } }